//! 🎟️ Actual close effects and logical CPU remain independent under one genuine Original.
use semio_framework_job_context::testkit;
use crate::{OriginalJobFixtureCaller,OriginalTurnFailure,OriginalTurnPrimary,OperationId,Generation,close_original_retained_step,close_original_effect_step,close_original_nested_step};
use crate::original_failure_test_support::{wire_value,wire_progress,projected};
use semio_framework_diagnostic::FaultMessageOwner;
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
use semio_framework_value::{RetainedCloneGrant,RetainedCloneProgress as P,RetirementDemand,RetainedWorkOutcome,retirement::controlled::ControlledRetirement};
use serde_json::{Value,json};
fn clock()->Option<u64>{Some(0)}
fn message(cx:&mut crate::StepContext<'_>,text:&str)->FaultMessageOwner{let(turn,heap)=observe(||FaultMessageOwner::construct(text,cx.retained_grant()));cx.consume_work(turn.work);let(owner,p)=turn.result.unwrap();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));cx.consume_retained(p).unwrap();owner}
fn close<T:semio_framework_value::retirement::RetireOwned>(value:T,cx:&mut crate::StepContext<'_>,bound:usize){let mut owner=ControlledRetirement::retain(value);for _ in 0..bound{if owner.terminal_is_empty(){break}let d=owner.next_demand(cx.retained_grant().maximum_copy_bytes).unwrap();let before=cx.fuel_remaining();let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||close_original_effect_step(cx,d,|effect|{owner.step(body,effect)}));let p=result.unwrap().progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(u128::from(before-cx.fuel_remaining()),owner.last_turn_work());}assert!(owner.terminal_is_empty());let(_,heap)=observe(||drop(owner));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
#[test]
fn quoted_original_close_denies_zero_fuel_and_preserves_partial_owner(){
 let policy:Value=serde_json::from_str(include_str!("../../../../⚠️failure/🎟️work/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["stock"].clone()).unwrap();
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()+43),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap());
 caller.turn(stock,|cx|{let mut owner=ControlledRetirement::retain(7u64);let mut denials=0;for _ in 0..128{if owner.terminal_is_empty(){break}let d=owner.next_demand(cx.retained_grant().maximum_copy_bytes)?;let work=owner.next_computational_work(cx.retained_grant().maximum_copy_bytes)?;let before=owner.next_demand(cx.retained_grant().maximum_copy_bytes)?;let mut called=false;
 let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||cx.with_original_work_loan(0,cx.deadline_us(),|same|close_original_effect_step(same,d,|effect|{called=true;owner.step(body,effect)})));assert_eq!(result?.progress(),P::default());assert!(!called);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(owner.next_demand(cx.retained_grant().maximum_copy_bytes)?,before);denials+=1;
 let before_fuel=cx.fuel_remaining();let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||close_original_effect_step(cx,d,|effect|owner.step(body,effect)));let progress=result?.progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));assert_eq!(u128::from(before_fuel-cx.fuel_remaining()),owner.last_turn_work());assert!(owner.last_turn_work()<=u128::from(work));
 }assert!(owner.terminal_is_empty());assert!(denials>1);Ok(())}).unwrap();caller.retire(stock);
}
#[test]
fn quoted_close_keeps_the_failed_producer_and_distinct_work_refusal(){
 let policy:Value=serde_json::from_str(include_str!("../../../../⚠️failure/🎟️work/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["stock"].clone()).unwrap();
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()+44),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap());
 caller.turn(stock,|cx|{let before=cx.fuel_remaining();let mut effects=0u64;let(result,heap)=observe(||crate::close_original_quoted_retained_step(cx,RetirementDemand{depth:1,..Default::default()},1,|_|{effects+=1;std::hint::black_box(effects);effects+=1;std::hint::black_box(effects);RetainedWorkOutcome{result:Err(semio_framework_value::ValueError::literal(semio_framework_value::ValueRefusalKind::InvalidValue,"original selected close failed")),work:u128::from(effects)}}));let failure=result.unwrap_err();assert_eq!(effects,2);assert_eq!(before-cx.fuel_remaining(),effects);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(failure.primary.message(),"original selected close failed");assert_eq!(failure.work_refusal().unwrap().message,"original close exceeded its admitted work quote");close(failure,cx,512);Ok(())}).unwrap();caller.retire(stock);
}
#[test]
fn original_close_posts_real_effects_exact_cpu_and_complete_refusals_including_zero_work(){
 let law:Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let policy:Value=serde_json::from_str(include_str!("../../../../⚠️failure/🎟️work/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["stock"].clone()).unwrap();let bound=law["maximumObservedTurns"].as_u64().unwrap()as usize;
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()+4),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap());
 caller.turn(stock,|cx|{
  let text=law["message"].as_str().unwrap();let source=message(cx,text);let mut owner=ControlledRetirement::retain(source);let d=owner.next_demand(cx.retained_grant().maximum_copy_bytes)?;let fuel=cx.fuel_remaining();let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||close_original_effect_step(cx,d,|effect|{owner.step(body,effect)}));let p=result?.progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(u128::from(fuel-cx.fuel_remaining()),owner.last_turn_work());assert!(owner.last_turn_work()>0);
  let stale=owner.last_turn_work();let d=owner.next_demand(cx.retained_grant().maximum_copy_bytes)?;let available=cx.retained_grant();
  for axis in law["deniedAxes"].as_array().unwrap(){let mut denied=available;match axis.as_str().unwrap(){"items"=>denied.maximum_items=0,"copy" if d.copy_bytes>0=>denied.maximum_copy_bytes=d.copy_bytes-1,"capacity" if d.capacity_bytes>0=>denied.maximum_capacity_bytes=d.capacity_bytes-1,"release" if d.release_bytes>0=>denied.maximum_release_bytes=d.release_bytes-1,"depth" if d.depth>0=>denied.maximum_depth=d.depth-1,_=>continue}let before=cx.retained_progress();let fuel=cx.fuel_remaining();let mut called=false;let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||cx.with_retained_loan(denied,|same|close_original_effect_step(same,d,|effect|{called=true;owner.step(body,effect)})));assert_eq!(result?.progress(),P::default());assert!(!called);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_progress(),before);assert_eq!(cx.fuel_remaining(),fuel);assert_eq!(owner.last_turn_work(),stale);}
  for _ in 0..bound{if owner.terminal_is_empty(){break}let d=owner.next_demand(cx.retained_grant().maximum_copy_bytes)?;let fuel=cx.fuel_remaining();let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||close_original_effect_step(cx,d,|effect|{owner.step(body,effect)}));let p=result?.progress();assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(p.retained_capacity_bytes,p.released_bytes));assert_eq!(u128::from(fuel-cx.fuel_remaining()),owner.last_turn_work());}assert!(owner.terminal_is_empty());
  let fuel=cx.fuel_remaining();let before=cx.retained_progress();let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||close_original_effect_step(cx,Default::default(),|effect|{owner.step(body,effect)}));assert_eq!(result?.progress(),P::default());assert_eq!(fuel-cx.fuel_remaining(),law["terminalQueryWork"].as_u64().unwrap());assert_eq!(cx.retained_progress(),before);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  let mut occupied=None;let mut occupied_source=message(cx,text);let source_pointer=occupied_source.fault().unwrap().message.as_ptr();let fuel=cx.fuel_remaining();let(result,heap)=observe(||close_original_nested_step(cx,|same,grant|{let turn=occupied_source.take_step(&mut occupied,grant);same.consume_work(turn.work);let p=turn.result?.progress();same.consume_retained(p)?;Ok(crate::InteractiveJobCloseStep::Pending{progress:p})}));result?;assert_eq!(fuel-cx.fuel_remaining(),law["headerTransferWork"].as_u64().unwrap());assert_eq!(occupied.as_ref().unwrap().message.as_ptr(),source_pointer);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(_,heap)=observe(||drop(occupied_source));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let mut candidate=message(cx,text);let pointer=candidate.fault().unwrap().message.as_ptr();let occupied_pointer=occupied.as_ref().unwrap().message.as_ptr();
  let saved=*testkit::retained_grant_mut(cx);testkit::retained_grant_mut(cx).maximum_capacity_bytes=cx.retained_progress().retained_capacity_bytes-1;let fuel=cx.fuel_remaining();let before=cx.retained_progress();
  let operation=cx.operation();let(result,heap)=observe(||close_original_nested_step(cx,|same,_|{let mut result=close_original_retained_step(same,RetirementDemand{depth:1,..Default::default()},|grant|candidate.take_step(&mut occupied,grant));*testkit::operation_mut(same)=OperationId(policy["foreignOperation"].as_u64().unwrap());if let Err(failure)=&mut result{failure.context_refusal=same.original_source_parent()?.validate_borrowed_context(same).err();}result}));*testkit::operation_mut(cx)=operation;*testkit::retained_grant_mut(cx)=saved;let failure=result.unwrap_err();assert_eq!(fuel-cx.fuel_remaining(),law["receiverValidationWork"].as_u64().unwrap());assert_eq!(cx.retained_progress(),before);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(matches!(&failure.primary,OriginalTurnPrimary::Value(error)if error.message==law["receiverMessage"].as_str().unwrap()));assert_eq!(projected(&failure,&mut Vec::new()),json!({"primary":{"kind":"value","original":wire_value("invariantViolated",law["receiverMessage"].as_str().unwrap(),P::default())},"receiptRefusal":wire_value("invariantViolated",law["receiptMessage"].as_str().unwrap(),P::default()),"contextRefusal":wire_value("invariantViolated",law["contextMessage"].as_str().unwrap(),P::default()),"effects":wire_progress(P::default())}));assert_eq!(candidate.fault().unwrap().message.as_ptr(),pointer);assert_eq!(occupied.as_ref().unwrap().message.as_ptr(),occupied_pointer);
  let saved=*testkit::retained_grant_mut(cx);testkit::retained_grant_mut(cx).maximum_capacity_bytes=cx.retained_progress().retained_capacity_bytes-1;let fuel=cx.fuel_remaining();let before=cx.retained_progress();let body=cx.retained_grant().maximum_copy_bytes;let(result,heap)=observe(||close_original_effect_step(cx,Default::default(),|effect|{owner.step(body,effect)}));*testkit::retained_grant_mut(cx)=saved;let zero_failure=result.unwrap_err();assert_eq!(fuel-cx.fuel_remaining(),0);assert_eq!(cx.retained_progress(),before);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(matches!(&zero_failure.primary,OriginalTurnPrimary::Value(error)if error.message==law["receiptMessage"].as_str().unwrap()));assert_eq!(zero_failure.effects,P::default());
  let(_,heap)=observe(||drop(owner));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close((candidate,occupied,failure,zero_failure),cx,bound);Ok(())
 }).unwrap();caller.retire(stock);
}


#[test]
fn normal_original_receiver_keeps_actual_child_cpu_primary_receipt_and_context_independently(){
 let law:Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let policy:Value=serde_json::from_str(include_str!("../../../../⚠️failure/🎟️work/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let stock:RetainedCloneGrant=serde_json::from_value(policy["stock"].clone()).unwrap();let bound=law["maximumObservedTurns"].as_u64().unwrap()as usize;
 let mut caller=OriginalJobFixtureCaller::admit(OperationId(policy["operation"].as_u64().unwrap()+9),Generation(policy["generation"].as_u64().unwrap()),stock,clock,policy["deadlineUs"].as_u64().unwrap(),policy["fuel"].as_u64().unwrap());
 caller.turn(stock,|cx|{
  let mut occupied=None;let mut source=message(cx,law["message"].as_str().unwrap());let turn=source.take_step(&mut occupied,cx.retained_grant());cx.consume_work(turn.work);cx.consume_retained(turn.result?.progress())?;assert!(source.terminal_is_empty());drop(source);let mut candidate=message(cx,law["message"].as_str().unwrap());let pointer=candidate.fault().unwrap().message.as_ptr();
  let grant=cx.retained_grant();let fuel=cx.fuel_remaining();let before=cx.retained_progress();let operation=cx.operation();let saved=*testkit::retained_grant_mut(cx);let(turn,heap)=observe(||candidate.take_step(&mut occupied,grant));assert_eq!(turn.work,u128::from(law["receiverValidationWork"].as_u64().unwrap()));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
  testkit::retained_grant_mut(cx).maximum_capacity_bytes=before.retained_capacity_bytes-1;*testkit::operation_mut(cx)=OperationId(policy["foreignOperation"].as_u64().unwrap());let(result,heap)=observe(||crate::receive_original_retained_work(cx,turn));*testkit::operation_mut(cx)=operation;*testkit::retained_grant_mut(cx)=saved;let failure=result.unwrap_err();assert_eq!(fuel-cx.fuel_remaining(),law["receiverValidationWork"].as_u64().unwrap());assert_eq!(cx.retained_progress(),before);assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(candidate.fault().unwrap().message.as_ptr(),pointer);
  assert_eq!(projected(&failure,&mut Vec::new()),json!({"primary":{"kind":"value","original":wire_value("invariantViolated",law["receiverMessage"].as_str().unwrap(),P::default())},"receiptRefusal":wire_value("invariantViolated",law["receiptMessage"].as_str().unwrap(),P::default()),"contextRefusal":wire_value("invariantViolated",law["contextMessage"].as_str().unwrap(),P::default()),"effects":wire_progress(P::default())}));close((candidate,occupied,failure),cx,bound);Ok(())
 }).unwrap();caller.retire(stock);
}
